package com.shiphappens.logistics.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.MediaType; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class IntegrationApiKeyFilter extends OncePerRequestFilter { private final String key; public IntegrationApiKeyFilter(@Value("${app.security.integration-api-key}") String key){this.key=key;} @Override protected boolean shouldNotFilter(HttpServletRequest request){return !request.getRequestURI().startsWith("/api/v1/integrations/");} @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException {if(!key.equals(request.getHeader("X-API-KEY"))){response.setStatus(401);response.setContentType(MediaType.APPLICATION_JSON_VALUE);response.getWriter().write("{\"error\":\"UNAUTHORIZED\",\"message\":\"Valid X-API-KEY is required\"}");return;}chain.doFilter(request,response);} }
